package com.nextfeet.nextfeet.cart; import java.util.*; import java.math.*; import org.springframework.stereotype.Service; import com.nextfeet.nextfeet.model.Zapatilla; @Service public class CarritoServiceImpl implements CarritoService {private final CarritoDAO dao; public CarritoServiceImpl(CarritoDAO dao){this.dao=dao;} public List<Zapatilla> listar(Integer u){return dao.listar(u);} public void agregar(Integer u,Integer z,String t,int q){dao.agregar(u,z,t,q);} public void actualizar(Integer u,Integer z,String t,int q){dao.actualizar(u,z,t,q);} public void eliminar(Integer u,Integer z,String t){dao.eliminar(u,z,t);} public void vaciar(Integer u){dao.vaciar(u);} public BigDecimal total(Integer u){return dao.total(u);}}